#include "cpuSw_dataAnalysis_dataAnalysis.h"

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

void cpuSw_dataAnalysis_dataAnalysis_initialize(void);
void cpuSw_dataAnalysis_dataAnalysis_notify(microkit_channel channel);
void cpuSw_dataAnalysis_dataAnalysis_timeTriggered(void);

volatile sb_queue_Common_Request_Impl_1_t *request_log_queue_1;
volatile sb_queue_Common_AnalysisReport_Impl_1_t *analysis_report_queue_1;
volatile sb_queue_Common_ResponseLog_Impl_1_t *response_log_queue_1;
sb_queue_Common_ResponseLog_Impl_1_Recv_t response_log_recv_queue;
volatile sb_queue_Common_AnalysisRequest_Impl_1_t *analysis_request_queue_1;
sb_queue_Common_AnalysisRequest_Impl_1_Recv_t analysis_request_recv_queue;

#define PORT_FROM_MON 0

bool put_request_log(const Common_Request_Impl *data) {
  sb_queue_Common_Request_Impl_1_enqueue((sb_queue_Common_Request_Impl_1_t *) request_log_queue_1, (Common_Request_Impl *) data);

  return true;
}

bool put_analysis_report(const Common_AnalysisReport_Impl *data) {
  sb_queue_Common_AnalysisReport_Impl_1_enqueue((sb_queue_Common_AnalysisReport_Impl_1_t *) analysis_report_queue_1, (Common_AnalysisReport_Impl *) data);

  return true;
}

bool response_log_is_empty(void) {
  return sb_queue_Common_ResponseLog_Impl_1_is_empty(&response_log_recv_queue);
}

bool get_response_log_poll(sb_event_counter_t *numDropped, Common_ResponseLog_Impl *data) {
  return sb_queue_Common_ResponseLog_Impl_1_dequeue((sb_queue_Common_ResponseLog_Impl_1_Recv_t *) &response_log_recv_queue, numDropped, data);
}

bool get_response_log(Common_ResponseLog_Impl *data) {
  sb_event_counter_t numDropped;
  return get_response_log_poll (&numDropped, data);
}

bool analysis_request_is_empty(void) {
  return sb_queue_Common_AnalysisRequest_Impl_1_is_empty(&analysis_request_recv_queue);
}

bool get_analysis_request_poll(sb_event_counter_t *numDropped, Common_AnalysisRequest_Impl *data) {
  return sb_queue_Common_AnalysisRequest_Impl_1_dequeue((sb_queue_Common_AnalysisRequest_Impl_1_Recv_t *) &analysis_request_recv_queue, numDropped, data);
}

bool get_analysis_request(Common_AnalysisRequest_Impl *data) {
  sb_event_counter_t numDropped;
  return get_analysis_request_poll (&numDropped, data);
}

void init(void) {
  printf("%s | INIT!\n", microkit_name);

  sb_queue_Common_Request_Impl_1_init((sb_queue_Common_Request_Impl_1_t *) request_log_queue_1);

  sb_queue_Common_AnalysisReport_Impl_1_init((sb_queue_Common_AnalysisReport_Impl_1_t *) analysis_report_queue_1);

  sb_queue_Common_ResponseLog_Impl_1_Recv_init(&response_log_recv_queue, (sb_queue_Common_ResponseLog_Impl_1_t *) response_log_queue_1);

  sb_queue_Common_AnalysisRequest_Impl_1_Recv_init(&analysis_request_recv_queue, (sb_queue_Common_AnalysisRequest_Impl_1_t *) analysis_request_queue_1);

  cpuSw_dataAnalysis_dataAnalysis_initialize();

  microkit_notify(PORT_FROM_MON);
}

void notified(microkit_channel channel) {
  switch (channel) {
    case PORT_FROM_MON:
      cpuSw_dataAnalysis_dataAnalysis_timeTriggered();
      break;
    default:
      cpuSw_dataAnalysis_dataAnalysis_notify(channel);
  }
}
